import convex from '@turf/convex'
import { featureCollection, point } from '@turf/helpers'
import { makeUnprojector } from './geojsonToStl.js'

/**
 * Project each solid's STL vertices onto its horizontal footprint.
 * X=east, Y=up, Z=south: unproject [x,-z] around the WGS84 origin.
 * Record solid name, facet count, base Y and top Y in h for STL extrusion.
 * Input: one solid spanning x=0..10, y=2..12, z=-10..0; origin [10,20].
 * Output: one GeoJSON Polygon near [10,20], with h:12 and min_height:2.
 */
// shortcut: convex hulls omit concavities and courtyards; reconstruct boundary edges if exact footprints are required.
export function stlFootprints(solids, origin) {
  const unproject = makeUnprojector(origin)
  const features = []
  for (const solid of solids) {
    const points = []
    let top = -Infinity,
      base = Infinity
    for (let i = 0; i < solid.positions.length; i += 3) {
      const p = solid.positions
      points.push(point(unproject([p[i], -p[i + 2]])))
      top = Math.max(top, p[i + 1])
      base = Math.min(base, p[i + 1])
    }
    const hull = points.length >= 3 ? convex(featureCollection(points)) : null
    if (!hull) continue
    hull.id = solid.name
    hull.properties = { name: solid.name, h: +top.toFixed(3), min_height: +base.toFixed(3), facets: solid.count }
    features.push(hull)
  }
  return featureCollection(features)
}
